import React, { useState } from "react"

import "./genie-intro.css"

function Message() {
  return (
    <p>
      Hey! Meet{" "}
      <a
        href="https://github.com/miragejs/orm"
        target="_blank"
        rel="noopener noreferrer"
      >
        @miragejs/orm
      </a>{" "}
      — a modern, type-safe rework of MirageJS with a fresh API and the same
      philosophy!
    </p>
  )
}

export default function GenieIntro() {
  const [isActivated, setIsActivated] = useState(false)

  const handleActivate = () => {
    if (isActivated) return
    setIsActivated(true)
  }

  const handleClose = () => {
    setIsActivated(false)
  }

  return (
    <div className={`genie-scene ${isActivated ? "activated" : ""}`}>
      {/* Genie behind smoke (z-index 1) */}
      <div className="genie-container">
        <GenieSvg />
      </div>

      {/* Smoke from lamp neck (z-index 2) */}
      <div className="smoke-from-neck" aria-hidden="true">
        <SmokeSvg />
      </div>

      {/* Lamp: float + shadow + sparks (z-index 3) */}
      <div className="lamp-container" aria-hidden="true">
        <button
          type="button"
          className="lamp-button"
          onClick={handleActivate}
          aria-label="Reveal information about miragejs/orm"
        >
          <LampSvg />
        </button>
      </div>

      {/* Speech bubble (z-index 4) */}
      <div className="speech-bubble">
        <button
          type="button"
          className="speech-bubble-close"
          onClick={handleClose}
          aria-label="Close"
        >
          <svg
            width="10"
            height="10"
            viewBox="0 0 10 10"
            fill="none"
            aria-hidden="true"
          >
            <path
              d="M1 1l8 8M9 1l-8 8"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
            />
          </svg>
        </button>
        <Message />
      </div>
    </div>
  )
}

